package com.quincaisoft.tenders.web;import com.quincaisoft.tenders.api.*;import com.quincaisoft.purchasing.api.PayablesService;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/api/v1")public class SettlementController{
 private final SettlementService service;private final PayablesService payables;public SettlementController(SettlementService service,PayablesService payables){this.service=service;this.payables=payables;}private void key(String k,UUID op){if(!UUID.fromString(k).equals(op))throw new IllegalArgumentException("Idempotency-Key mismatch");}
 @GetMapping("/settlements")@PreAuthorize("hasAnyAuthority('tenders:read','SCOPE_tenders:read')")public List<SettlementService.Settlement> list(){return service.list();}
 @GetMapping("/payables")@PreAuthorize("hasAnyAuthority('purchasing:read','SCOPE_purchasing:read')")public List<PayablesService.Balance> balances(){return payables.balances();}
 @GetMapping("/supplier-advances")@PreAuthorize("hasAnyAuthority('purchasing:read','SCOPE_purchasing:read')")public List<PayablesService.Advance> advances(){return payables.advances();}
 @PostMapping("/settlements/supplier-payment")@PreAuthorize("hasAnyAuthority('tenders:supplier-pay','SCOPE_tenders:supplier-pay')")public SettlementService.Settlement supplierPayment(@RequestHeader("Idempotency-Key")String k,@RequestBody SettlementService.Payment p){key(k,p.operationId());return service.supplierPayment(p);}
 @PostMapping("/supplier-advances")@PreAuthorize("hasAnyAuthority('tenders:supplier-pay','SCOPE_tenders:supplier-pay')")public SettlementService.Settlement advance(@RequestHeader("Idempotency-Key")String k,@RequestBody SettlementService.Payment p){key(k,p.operationId());return service.supplierAdvance(p);}
 @PostMapping("/supplier-advances/allocate")@PreAuthorize("hasAnyAuthority('tenders:supplier-pay','SCOPE_tenders:supplier-pay')")public SettlementService.Settlement allocate(@RequestHeader("Idempotency-Key")String k,@RequestBody SettlementService.Allocate p){key(k,p.operationId());return service.allocateAdvance(p);}
 @PostMapping("/settlements/bank-receipt")@PreAuthorize("hasAnyAuthority('tenders:write','SCOPE_tenders:write')")public SettlementService.Settlement receipt(@RequestHeader("Idempotency-Key")String k,@RequestBody SettlementService.Payment p){key(k,p.operationId());return service.bankReceipt(p);}
 @PostMapping("/settlements/bank-deposit")@PreAuthorize("hasAnyAuthority('tenders:write','SCOPE_tenders:write')")public SettlementService.Settlement deposit(@RequestHeader("Idempotency-Key")String k,@RequestBody SettlementService.Payment p){key(k,p.operationId());return service.bankDeposit(p);}
 @GetMapping("/settlements/{id}")@PreAuthorize("hasAnyAuthority('tenders:read','SCOPE_tenders:read')")public SettlementService.Settlement get(@PathVariable UUID id){return service.get(id);}
}
